562		path := newTestLedger(t, []BalanceInit{{Account: "aa", Asset: "usdc", Balance: 1000}})
563		l := openOrFail(t, path)
564		SetFailHook(l, &failNth{nth: 2}) // ok1 落盘成功，boom 落盘失败，ok2 再次成功
565		t.Cleanup(func() { SetFailHook(l, nil) })
566	
567		res, err := l.Submit(FeeBatch{FeeBps: 0, Intents: []PaymentIntent{
568			intent("ok1", "aa", "usdc", 100),  // 成功
569			intent("boom", "aa", "usdc", 100), // 保存失败 → 回滚该项
570			intent("ok2", "aa", "usdc", 100),  // 注入只失败一次，后续成功
571		}})
572		if err != nil {
573			t.Fatal(err)
574		}
575		want := []string{StatusSettled, StatusStorage, StatusSettled}
576		if got := statuses(res); fmt.Sprint(got) != fmt.Sprint(want) {
577			t.Fatalf("statuses=%v want %v", got, want)
578		}
579		if bal, _ := l.Balance("aa", "usdc"); bal != 800 {
580			t.Fatalf("balance=%d want 800 (前项与后项保留，失败项回滚)", bal)
581		}
582		snap, _ := l.Query()
583		if len(snap.Settlements) != 2 || snap.Settlements[0].ID != "ok1" || snap.Settlements[1].ID != "ok2" {
584			t.Fatalf("records after storage failure: %+v", snap.Settlements)
585		}
586	
587		// 失败编号不占去重资格，可以重新提交成功。
588		res2, _ := l.Submit(FeeBatch{FeeBps: 0, Intents: []PaymentIntent{intent("boom", "aa", "usdc", 100)}})
589		if res2.Results[0].Status != StatusSettled {
590			t.Fatalf("failed-on-storage id retry: %+v", res2.Results[0])
591		}
592	
593		// 关闭重开：磁盘状态与内存一致，失败项不留痕。
594		l2 := openOrFail(t, path)
595		snap2, _ := l2.Query()
596		if len(snap2.Settlements) != 3 {
597			t.Fatalf("after reopen want 3 records, got %+v", snap2.Settlements)
598		}
599		if bal, _ := l2.Balance("aa", "usdc"); bal != 700 {
600			t.Fatalf("after reopen balance=%d want 700", bal)
601		}
602	}
