		}
	}
	if r.Record != nil {
		t.Fatalf("limit_exceeded must not carry a record: %+v", r.Record)
	}
	// 超限项不扣余额、不留记录；未列出组合正常扣款。
	if bal, _ := l.Balance("aa", "usdc"); bal != 9000 {
		t.Fatalf("usdc balance=%d want 9000", bal)
